// cspell:disable-file
/// One emoji the reaction picker can offer.
///
/// [name] is the Unicode name, already lowercase, and [group] is the catalog
/// section it is drawn under.
class ChatEmoji {
  /// Creates one catalog entry.
  const ChatEmoji(this.emoji, this.name, this.group);

  /// The emoji itself, fully qualified.
  final String emoji;

  /// The CLDR name, used as the tooltip and the search text.
  final String name;

  /// The section heading this emoji is listed under.
  final String group;
}

/// Every emoji [ChatEmojiPicker] can offer: the fully-qualified emoji from
